/// One page of the frame: its one name (the site's too), its path ({league} is the club's league; a path
/// without it opens over the club), its glyph (a GameGlyph name) and its line icon (brand/icons, the site's).
class NavPage {
  const NavPage(this.key, {required this.ar, required this.en, required this.path, required this.glyph, required this.icon});

  final String key, ar, en, path, glyph, icon;

  String label(String locale) => locale == 'ar' ? ar : en;
  String route(int league) => path.replaceAll('{league}', '$league');
  bool get push => !path.contains('{league}');
}

